import{_ as l,l as o,o as e,c as n,v as t,p as s,x as i,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"指令嵌入","description":"","frontmatter":{"title":"指令嵌入","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/instruction-embeddings.md","filePath":"llm/instruction-embeddings.md","lastUpdated":1789023840000}'),h={name:"llm/instruction-embeddings.md"};function E(c,a,_,u,T,B){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="指令嵌入" tabindex="-1">指令嵌入 <a class="header-anchor" href="#指令嵌入" aria-label="Permalink to &quot;指令嵌入&quot;">​</a></h1><div class="epigraph"><p>同一句话，用作检索查询、用作要被检索的文档、用作聚类对象，需要的向量不同。把任务写成前缀指令，嵌入模型才知道该挤出哪一种语义。</p><footer>—— Su 等 INSTRUCTOR；后续 E5-Mistral / 指令式检索模型同一接口</footer></div><p><a href="/llm/matryoshka-embeddings">上一课</a>把维数当预算。还剩条件：双塔若永远用同一编码器无前缀，查询与文档、对称相似与非对称检索会互相伤害。本课写指令嵌入。缺口是任务条件化。后课多向量默认单向量已经按指令对齐，仍不够时再上晚交互。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「苹果」在新闻检索、产品搜索、聚类里应靠近不同的邻居。无指令的句向量只能学一个折中空间。Su 等人的 INSTRUCTOR 把自然语言指令拼在文本前，训练时覆盖检索、分类、聚类等任务，推理时改指令即改几何。查询侧指令（「把这个问题编成检索向量」）与文档侧指令（「把这段当成可检索段落」）可以不对称，这正是非对称检索需要的。</p><p>与生成式指令微调同构，但损失仍是对比，不是下一词。不要把 LLM 聊天模板原样套到嵌入模型上而不做对比训练。</p><p><span class="marginnote">指令是条件，不是第二个要交叉注意的句子。池化发生在「指令+文本」的整段双向表示上，见池化课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练数据要带任务指令，覆盖目标用例；指令多样性不足时，模型只学会几个模板。评测用 <a href="/llm/mteb">MTEB</a> 时，必须用该任务官方指令，否则与别人的分数不可比。部署：查询实时加指令，文档侧指令在建索引时写入——改指令等于重建索引。</p>',9)),(e(),s(p,null,{default:i(()=>[m(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INST%5B%22%E4%BB%BB%E5%8A%A1%E6%8C%87%E4%BB%A4%22%5D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20ENC%0A%20%20ENC%20--%3E%20Z%5B%22%E6%9D%A1%E4%BB%B6%E5%8F%A5%E5%90%91%E9%87%8F%22%5D%0A%20%20Z%20--%3E%20TASK%5B%22%E6%A3%80%E7%B4%A2%20%2F%20%E8%81%9A%E7%B1%BB%20%2F%20%E5%88%86%E7%B1%BB%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指令 token 改变注意力下的汇聚：检索指令强调可匹配的关键约束，聚类指令强调主题，分类指令强调标签相关特征。对比损失把同一指令下的正对拉近。跨指令的几何不必连续——不要假设「改几个字指令」向量只小幅移动。因此指令要版本化，像聊天模板一样冻结。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指令不能替代相关性标注：再好的前缀也救不了假正例。超长指令会占掉文档有效长度。下一课多向量与晚交互：单向量条件化之后，仍需要 token 级交互的任务。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指令前缀让同一编码器服务多种度量任务，查询/文档可非对称。</li><li>改文档指令必须重建索引；评测锁官方指令。</li><li>损失仍是对比，不是聊天 SFT。</li><li>出处：Su 等 INSTRUCTOR；E5-Mistral 等指令检索模型。</li></ul>',6))])}const b=l(h,[["render",E]]);export{f as __pageData,b as default};
